/// The first non-empty value among `keys`, taken from the first JSON object
/// in `text` that carries one.
///
/// Scanning past a failed candidate matters because models sometimes
/// precede the object with prose containing a brace, and the salvage pass
/// matters because an envelope truncated mid-string — or written with
/// unescaped line breaks — still holds a usable answer.
static func stringField(anyOf keys: [String], in text: String) -> String? {
    for candidate in jsonObjectCandidates(in: text) {
        guard let data = candidate.data(using: .utf8),
              let object = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else { continue }
        for key in keys {
            guard let value = object[key] as? String,
                  !value.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { continue }
            return value
        }
    }
    return salvagedField(anyOf: keys, in: text)
}

