//
//  AudioCaptureService.swift
//  SwiftMandarin
//
//  Records short audio clips for the Multimodal tab and previews app-owned
//  recordings/imports. Source audio remains local and is never sent to
//  MiniMax; transcription is handled separately by Apple's Speech framework.
//

import Foundation
import Observation
import UniformTypeIdentifiers
@preconcurrency import AVFAudio
@preconcurrency import AVFoundation

nonisolated enum AudioCaptureError: LocalizedError {
    case microphoneNotAuthorized
    case recorderCouldNotStart
    case noActiveRecording
    case emptyRecording
    case unsupportedFile
    case fileTooLarge(maximumMegabytes: Int)
    case audioTooLong(maximumSeconds: Int)
    case fileAccessFailed(String)
    case previewFailed(String)

    var errorDescription: String? {
        switch self {
        case .microphoneNotAuthorized:
            #if os(iOS)
            return String(localized: "Microphone access is required to record audio. Enable it in Settings, or import an audio file instead.")
            #else
            return String(localized: "Microphone access is required to record audio. Enable it in System Settings, or import an audio file instead.")
            #endif
        case .recorderCouldNotStart:
            return String(localized: "The audio recorder could not start. Check that another app is not using the microphone and try again.")
        case .noActiveRecording:
            return String(localized: "There is no recording to stop.")
        case .emptyRecording:
            return String(localized: "The recording did not contain any audio. Please record again.")
        case .unsupportedFile:
            return String(localized: "Choose a playable audio file such as M4A, MP3, WAV, AIFF, or CAF.")
        case .fileTooLarge(let maximumMegabytes):
            return String.localizedStringWithFormat(
                String(localized: "This audio file is too large. Choose a file smaller than %lld MB."),
                Int64(maximumMegabytes)
            )
        case .audioTooLong(let maximumSeconds):
            return String.localizedStringWithFormat(
                String(localized: "This audio is too long. Choose or record a clip no longer than %lld seconds."),
                Int64(maximumSeconds)
            )
        case .fileAccessFailed(let message):
            return String(localized: "The audio file could not be prepared:") + " " + message
        case .previewFailed(let message):
            return String(localized: "The audio preview could not start:") + " " + message
        }
    }
}

nonisolated enum AudioInputSource: Sendable, Equatable {
    case recording
    case importFile
}

/// Metadata for an app-owned temporary audio file. The original security-
/// scoped import is never retained; `url` always points into the app's temp
/// directory and can therefore be used safely by asynchronous recognition.
nonisolated struct PreparedAudioFile: Identifiable, Equatable, Sendable {
    let id: UUID
    let url: URL
    let displayName: String
    let byteCount: Int64
    let duration: TimeInterval?
    let source: AudioInputSource

    init(
        id: UUID = UUID(),
        url: URL,
        displayName: String,
        byteCount: Int64,
        duration: TimeInterval?,
        source: AudioInputSource
    ) {
        self.id = id
        self.url = url
        self.displayName = displayName
        self.byteCount = byteCount
        self.duration = duration
        self.source = source
    }
}

/// Copies and validates audio selected through a security-scoped file picker.
/// All expensive file work is kept off the main actor.
nonisolated enum AudioInputFileStore {
    static let maximumFileSize = 100 * 1_024 * 1_024
    static let maximumDurationSeconds: TimeInterval = 60

    private static let supportedExtensions: Set<String> = [
        "aac", "aif", "aiff", "caf", "m4a", "mp3", "wav"
    ]

    static func importAudio(from sourceURL: URL) async throws -> PreparedAudioFile {
        let originalName = sourceURL.lastPathComponent.isEmpty
            ? String(localized: "Imported Audio")
            : sourceURL.lastPathComponent
        let copiedURL: URL

        do {
            let hasScopedAccess = sourceURL.startAccessingSecurityScopedResource()
            let copyTask = Task.detached(priority: .userInitiated) {
                try copyValidatedAudio(from: sourceURL)
            }
            copiedURL = try await withTaskCancellationHandler {
                defer {
                    if hasScopedAccess {
                        sourceURL.stopAccessingSecurityScopedResource()
                    }
                }
                let url = try await copyTask.value
                do {
                    try Task.checkCancellation()
                } catch {
                    remove(url)
                    throw error
                }
                return url
            } onCancel: {
                copyTask.cancel()

    isRecording || isStartingRecording || isStartingPlayback
        || recorder != nil || playingURL != nil || player?.isPlaying == true
        || recordingSessionOwner != nil || playbackSessionOwner != nil
}

func startRecording() async throws {
    guard !isRecording, !isStartingRecording else { return }
    let requestID = UUID()
    recordingStartID = requestID
    completedRecordingURL = nil
    playbackErrorMessage = nil
    isStartingRecording = true
    defer {
        if recordingStartID == requestID {
            recordingStartID = nil
            isStartingRecording = false
        }
    }

    try Task.checkCancellation()
    guard await requestMicrophonePermissionIfNeeded() else {
        throw AudioCaptureError.microphoneNotAuthorized
    }
    try Task.checkCancellation()
    guard recordingStartID == requestID else { throw CancellationError() }

    stopPlayback()
    await SpeechRecognitionService.shared.stopRecording()
    try Task.checkCancellation()
    guard recordingStartID == requestID else { throw CancellationError() }
    SpeechService.stop()

    let fileManager = FileManager.default
    try fileManager.createDirectory(
        at: AudioInputFileStore.temporaryFolder,
        withIntermediateDirectories: true
    )
    let url = AudioInputFileStore.temporaryFolder
        .appendingPathComponent(UUID().uuidString)
        .appendingPathExtension("m4a")

    let settings: [String: Any] = [
        AVFormatIDKey: Int(kAudioFormatMPEG4AAC),
        AVSampleRateKey: 44_100,
        AVNumberOfChannelsKey: 1,
        AVEncoderAudioQualityKey: AVAudioQuality.high.rawValue,
        AVEncoderBitRateKey: 128_000
    ]
    let sessionOwner = AudioSessionOwner()

    do {
        SourceAudioActivityCoordinator.shared.acquire(self)
        recordingSessionOwner = sessionOwner
        try await AudioSessionCoordinator.shared.acquire(
            .clipRecording,
            owner: sessionOwner
        )
        try Task.checkCancellation()
        guard recordingStartID == requestID,
              recordingSessionOwner == sessionOwner else {
            AudioSessionCoordinator.shared.release(sessionOwner)
            throw CancellationError()
        }

        let recorder = try AVAudioRecorder(url: url, settings: settings)
        recorder.prepareToRecord()
        guard recorder.record() else {
            throw AudioCaptureError.recorderCouldNotStart
        }
        self.recorder = recorder
        recordingURL = url
        isRecording = true
    } catch {
        AudioSessionCoordinator.shared.release(sessionOwner)
        if recordingSessionOwner == sessionOwner {
            recordingSessionOwner = nil
        }
        AudioInputFileStore.remove(url)
        releaseSessionOwnershipIfIdle()
        if error is CancellationError {
            throw error
        }
        if let captureError = error as? AudioCaptureError {
            throw captureError
        }
        throw AudioCaptureError.fileAccessFailed(error.localizedDescription)
    }
}

func stopRecording() throws -> URL {
    guard let recorder, let recordingURL else {
        throw AudioCaptureError.noActiveRecording
    }

    recordingStartID = nil
    isStartingRecording = false
    recorder.stop()
    let sessionOwner = recordingSessionOwner
    recordingSessionOwner = nil
    self.recorder = nil
    self.recordingURL = nil
    isRecording = false
    if let sessionOwner {
        AudioSessionCoordinator.shared.release(sessionOwner)
    }
    releaseSessionOwnershipIfIdle()

    let byteCount = (try? recordingURL.resourceValues(forKeys: [.fileSizeKey]).fileSize) ?? 0
    guard byteCount > 0 else {
        AudioInputFileStore.remove(recordingURL)
        throw AudioCaptureError.emptyRecording
    }
    return recordingURL
}

func discardActiveRecording() {
    recordingStartID = nil
    isStartingRecording = false
    let sessionOwner = recordingSessionOwner
    recordingSessionOwner = nil
    recorder?.stop()
    recorder = nil
    isRecording = false
    if let recordingURL {
        AudioInputFileStore.remove(recordingURL)
    }
    recordingURL = nil
    if let sessionOwner {
        AudioSessionCoordinator.shared.release(sessionOwner)
    }
    releaseSessionOwnershipIfIdle()
}

func togglePlayback(of url: URL) async throws {
    if playingURL == url || isStartingPlayback {
        stopPlayback()
        return
    }

    stopPlayback()
    let requestID = UUID()
    let sessionOwner = AudioSessionOwner()
    playbackStartID = requestID
    isStartingPlayback = true
    do {
        await SpeechRecognitionService.shared.stopRecording()
        try Task.checkCancellation()
        guard playbackStartID == requestID else { throw CancellationError() }
        SpeechService.stop()
        playbackErrorMessage = nil

// MARK: - Actions

private func beginInputProcessingRequest() -> UUID {
    let requestID = UUID()
    inputProcessingRequestID = requestID
    return requestID
}

@discardableResult
private func commitIfCurrent(
    _ requestID: UUID,
    operation: () -> Void
) -> Bool {
    guard inputProcessingRequestID == requestID, !Task.isCancelled else {
        return false
    }
    operation()
    return true
}

/// Reuses the same editor, analysis, and language-specific translation
/// paths as typed or OCR text. The transcript is committed to the editor
/// before translation starts so learners can always inspect and correct it.
private func handleAudioInputResult(
    _ transcript: String,
    recognitionLanguage: SpeechRecognitionLanguage,
    action: MultimodalAudioAction
) async throws {
    guard !transcript.isEmpty, !Task.isCancelled else { return }

    // An audio result is newer than any in-flight photo/OCR work and must
    // not be overwritten when an older image task completes.
    photoProcessingTask?.cancel()
    textProcessingTask?.cancel()
    let requestID = beginInputProcessingRequest()
    aiFallbackTranslationTask?.cancel()
    englishTranslationRequestID = nil
    chineseTranslationTask?.cancel()
    chineseTranslationTask = nil
    chineseTranslationRequestID = nil
    isTranslating = false
    sourceText = transcript
    rawOCRText = ""
    aiCleanupApplied = false
    cleanupNotice = nil

    let knownLanguage: DetectedLanguage = recognitionLanguage == .english
        ? .english
        : .chinese
    await processText(
        transcript,
        knownLanguage: knownLanguage,
        requestID: requestID
    )
    try Task.checkCancellation()

    guard action == .translateAudio,
          !Task.isCancelled,
          inputProcessingRequestID == requestID else { return }
    if knownLanguage == .english {
        triggerTranslation()
        guard let translationRequestID = englishTranslationRequestID else {
            throw MultimodalAudioTranslationFailure(
                message: String(localized: "Translation failed.")
            )
        }
        try await waitForAudioTranslationCompletion(
            inputRequestID: requestID,
            translationRequestID: translationRequestID,
            language: .english
        )
        guard analyzedSentences.contains(where: {
            !($0.translation ?? "").trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        }) else {
            throw MultimodalAudioTranslationFailure(
                message: errorMessage ?? String(localized: "Translation failed.")
            )
        }
    } else {
        triggerChineseTranslation()
        guard let translationRequestID = chineseTranslationRequestID else {
            throw MultimodalAudioTranslationFailure(
                message: String(localized: "Translation failed.")
            )
        }
        try await waitForAudioTranslationCompletion(
            inputRequestID: requestID,
            translationRequestID: translationRequestID,
            language: .chinese
        )
        guard !chineseTranslation.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
            throw MultimodalAudioTranslationFailure(
                message: errorMessage ?? String(localized: "Translation failed.")
            )
        }
    }
}

/// Keeps the audio operation's progress and Cancel control alive through
/// the parent-owned translation. Cancelling the child task invalidates the
/// matching translation request so late provider results cannot commit.
private func waitForAudioTranslationCompletion(
    inputRequestID: UUID,
    translationRequestID: UUID,
    language: DetectedLanguage
) async throws {
    do {
        while true {
            try Task.checkCancellation()
            guard self.inputProcessingRequestID == inputRequestID else {
                throw CancellationError()
            }
            let isActive = language == .english
                ? englishTranslationRequestID == translationRequestID
                : chineseTranslationRequestID == translationRequestID
            if !isActive { return }
            try await Task.sleep(for: .milliseconds(50))
        }
    } catch {
        if language == .english,
           englishTranslationRequestID == translationRequestID {
            aiFallbackTranslationTask?.cancel()
            aiFallbackTranslationTask = nil
            englishTranslationRequestID = nil
        } else if language == .chinese,
                  chineseTranslationRequestID == translationRequestID {
            chineseTranslationTask?.cancel()
            chineseTranslationTask = nil
            chineseTranslationRequestID = nil
        }
        if englishTranslationRequestID == nil,
           chineseTranslationRequestID == nil {
            isTranslating = false
        }
        throw error
    }
}

private func loadAndProcessImage(
    _ item: PhotosPickerItem?,
    requestID: UUID
) async {
    guard inputProcessingRequestID == requestID,
          !Task.isCancelled else { return }
    guard let item else {

// MARK: - Actions

/// Determines the actual translation direction based on detected input language
/// According to the translation logic table:
/// - Input EN → Output ZH (regardless of setting)
/// - Input ZH → Output EN (regardless of setting)
private var detectedTranslationDirection: TranslationDirection {
    let sourceIsChinese = containsChinese(sharedState.sourceText)
    // If input is Chinese, translate to English; if input is English, translate to Chinese
    return sourceIsChinese ? .chineseToEnglish : .englishToChinese
}

private func triggerTranslation() {
    let trimmedSource = sharedState.sourceText.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !trimmedSource.isEmpty else { return }

    // Detect actual input language and use appropriate translation direction
    // This ensures: EN input → ZH output, ZH input → EN output
    let actualDirection = detectedTranslationDirection

    guard #available(iOS 18.0, macOS 15.0, *) else {
        // iOS 17: no on-device Translation API — use the AI provider.
        startAITranslation()
        return
    }

    // Apple's recommended pattern for triggering translations:
    // - First time: Create a new configuration
    // - When detected direction changes: Create new configuration
    // - Otherwise: Call invalidate() on existing configuration
    if translationConfiguration.isNil || lastDetectedDirection != actualDirection {
        // Create new configuration based on detected language
        lastDetectedDirection = actualDirection
        translationConfiguration.set(
            source: actualDirection.sourceLanguage,
            target: actualDirection.targetLanguage
        )
    } else {
        // Subsequent translation with same direction - invalidate to re-trigger
        translationConfiguration.invalidate()
    }
}

/// Start AI translation, cancelling any in-flight request first so
/// rapid taps can't pile up racing tasks.
private func startAITranslation() {
    aiTranslationTask?.cancel()
    aiTranslationTask = Task { await triggerAITranslation() }
}

private func triggerAITranslation() async {
    let sourceSnapshot = sharedState.sourceText.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !sourceSnapshot.isEmpty else { return }

    isAITranslating = true
    aiTranslationError = nil
    sharedState.translationError = nil

    do {
        // Detect actual input language (not based on the UI toggle).
        // EN input → ZH output, ZH input → EN output. History must record
        // the direction that actually happened, not what the toggle said.
        let sourceIsChinese = containsChinese(sourceSnapshot)
        let actualDirection: TranslationDirection = sourceIsChinese ? .chineseToEnglish : .englishToChinese

        let translation = try await AIWordExplanationService.shared.translateWithProvider(
            sourceSnapshot,
            sourceIsChinese: sourceIsChinese
        )

        // Only guard against a stale source text; the UI toggle is irrelevant
        // because the direction is derived from the (unchanged) source content.
        guard sharedState.sourceText.trimmingCharacters(in: .whitespacesAndNewlines) == sourceSnapshot else {
            isAITranslating = false
            return
        }

        sharedState.translatedText = translation
        isAITranslating = false
        handleCompletedTranslation(source: sourceSnapshot, target: translation, direction: actualDirection)
        // Have the AI identify the words/phrases in the Chinese side so the
        // tap-to-learn view uses real word boundaries, not NLTokenizer.
        startWordIdentification(for: activeChineseText)
    } catch {
        isAITranslating = false
        sharedState.translationError = "AI Translation failed: \(error.localizedDescription)"
        print("AI Translation error: \(error)")
    }
}

/// Ask the configured AI provider to identify the words/phrases in the
/// Chinese text, then feed them to the interactive ruby view. Cancels any
/// in-flight identification first. Silently falls back to local
/// segmentation (empty `aiSegments`) when no provider is available or the
/// request fails — the feature is additive, never blocking.
private func startWordIdentification(for chineseText: String) {
    wordIdentificationTask?.cancel()
    aiSegments = []

    let trimmed = chineseText.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !trimmed.isEmpty, aiSettings.isAnyProviderAvailable else {
        isIdentifyingWords = false
        return
    }

    // Generation guard: only the latest request may flip the spinner off,
    // so a superseded request's completion can't hide an in-flight one.
    wordIdGeneration += 1
    let generation = wordIdGeneration
    isIdentifyingWords = true

//
//  TranslationState.swift
//  SwiftMandarin
//
//  Shared state for translation that persists across tab switches
//

import SwiftUI
import Observation

/// Shared translation state that persists across tab switches
/// This allows users to switch tabs and return to their translation
@Observable
final class TranslationState {
    static let shared = TranslationState()

    var sourceText: String = ""
    var translatedText: String = ""
    var direction: TranslationDirection = .englishToChinese
    var isTranslating: Bool = false
    var translationError: String?

    private init() {}

    /// Restore from a history entry
    func restore(from entry: TranslationHistoryEntry) {
        sourceText = entry.source
        translatedText = entry.target
        direction = entry.direction
        translationError = nil
        isTranslating = false
    }

    /// Clear all translation state
    func clear() {
        sourceText = ""
        translatedText = ""
        translationError = nil
        isTranslating = false
    }

    /// Check if there's content to display
    var hasContent: Bool {
        !sourceText.isEmpty || !translatedText.isEmpty
    }
}

